export function deliveryModeLabel(mode: DeliveryMode) {
  if (mode === "pickup") {
    return "Pickup";
  }
  return "Shipping";
}

edits.newText:
export function deliveryModeLabel(mode: DeliveryMode) {
  if (mode === "pickup") {
    return "Pickup";
  }
  if (mode === "scheduled") {
    return "Scheduled delivery";
  }
  return "Shipping";
}
